import { description, uses } from "@decaf-ts/decoration";
import { column, createdAt, pk, table, updatedAt } from "@decaf-ts/core";
import { hideOn } from "@decaf-ts/db-decorators";
import { Model, ModelArg, email, maxlength, minlength, model, pattern, required } from "@decaf-ts/decorator-validation";
import { uielement, uilayoutprop, uilistmodel, uilistprop, uimodel } from "@decaf-ts/ui-decorators";

@description("Persisted application user")
@uses("ram")
@table("users")
@uilistmodel("ngx-decaf-list-item", { icon: "ti-user" })
@uimodel("ngx-decaf-crud-form", { cols: 2, rows: 2 })
@model()
class User extends Model {
  @pk()
  @uielement("ngx-decaf-crud-field", { label: "user.id.label" })
  @uilayoutprop(1, 1)
  id!: string;

  @column("email")
  @required()
  @email()
  @pattern(/^[^@\s]+@[^@\s]+\.[^@\s]+$/)
  @uielement("ngx-decaf-crud-field", { label: "user.email.label", type: "email" })
  @uilistprop("title")
  @uilayoutprop(1, 2)
  email!: string;

  @column("name")
  @required()
  @minlength(5)
  @maxlength(64)
  @uielement("ngx-decaf-crud-field", { label: "user.name.label" })
  @uilistprop("description")
  @uilayoutprop(2, 1)
  name!: string;

  @column("created_at")
  @createdAt()
  @hideOn("create", "update")
  @uielement("ngx-decaf-crud-field", { label: "user.createdAt.label", type: "date" })
  @uilayoutprop(2, 2)
  createdAt!: Date;

  @column("updated_at")
  @updatedAt()
  @hideOn("create", "update")
  @uielement("ngx-decaf-crud-field", { label: "user.updatedAt.label", type: "date" })
  @uilayoutprop(3, 1)
  updatedAt!: Date;

  constructor(arg?: ModelArg<User>) {
    super(arg);
  }
}

