import { Validator, Validation, validator, innerValidationDecorator, type, model, Model } from "@decaf-ts/decorator-validation";
import { apply } from "@decaf-ts/decoration";

const GTIN_KEY = "gtin";

@validator(GTIN_KEY)
class GtinValidator extends Validator {
  constructor() {
    super("Invalid GTIN");
  }

  hasErrors(value: string | number): string | undefined {
    return /^\d{14}$/.test(String(value)) ? undefined : this.getMessage();
  }
}

Validation.register(new GtinValidator());

const gtin = () =>
  apply(
    innerValidationDecorator(gtin, GTIN_KEY, { message: "Invalid GTIN", async: false }),
    type([String, Number])
  );

