import { query, prepared } from "@decaf-ts/core";

class UserRepo extends Repository<User, RamAdapter> {
  @query()
  async findActiveUsers() {
    return this.select().where(Condition.attr<User>("active").eq(true)).execute();
  }

  @prepared()
  async findByName(name: string) {
    return this.select().where(Condition.attr<User>("name").eq(name)).execute();
  }
}
